// Generates sources/data/nameFont.js: the outlines of just the glyphs the 3D
// world builds as physical letters (the name, the monogram and the social
// icons; see sources/data/name.js and social.js), in three.js "typeface"
// format, from Montserrat ExtraBold (SIL OFL 1.1).
//
//   npm run name-font
//
// Re-run after changing the name. Needs the dev dependencies opentype.js and
// @fontsource/montserrat; the game itself only ships the generated file.

import fs from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'
import opentype from 'opentype.js'

const require = createRequire(import.meta.url)
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..')
const { NAME, MONOGRAM } = await import(path.join(root, 'sources/data/name.js'))
const { default: social } = await import(path.join(root, 'sources/data/social.js'))
const text = [NAME, MONOGRAM, ...social.map((link) => link.icon ?? '')].join('')

const fontFile = require.resolve('@fontsource/montserrat/files/montserrat-latin-800-normal.woff')
const buffer = fs.readFileSync(fontFile)
const font = opentype.parse(buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength))

const scale = (100000) / ((font.unitsPerEm || 2048) * 72)
const round = (v) => Math.round(v * scale)
const glyphs = {}

for (const char of new Set(text.replace(/\s+/g, '')))
{
    const glyph = font.charToGlyph(char)
    const commands = glyph.getPath(0, 0, font.unitsPerEm).commands
    let o = ''
    for (const c of commands)
    {
        // opentype paths are y-down; typeface outlines are y-up
        switch (c.type)
        {
            case 'M': o += `m ${round(c.x)} ${round(-c.y)} `; break
            case 'L': o += `l ${round(c.x)} ${round(-c.y)} `; break
            case 'Q': o += `q ${round(c.x)} ${round(-c.y)} ${round(c.x1)} ${round(-c.y1)} `; break
            case 'C': o += `b ${round(c.x)} ${round(-c.y)} ${round(c.x1)} ${round(-c.y1)} ${round(c.x2)} ${round(-c.y2)} `; break
        }
    }
    glyphs[char] = {
        ha: round(glyph.advanceWidth),
        x_min: round(glyph.xMin ?? 0),
        x_max: round(glyph.xMax ?? 0),
        o: o.trim(),
    }
}

const typeface = {
    glyphs,
    familyName: 'Montserrat ExtraBold',
    ascender: round(font.ascender),
    descender: round(font.descender),
    underlinePosition: round(font.tables.post.underlinePosition),
    underlineThickness: round(font.tables.post.underlineThickness),
    boundingBox: { xMin: round(font.tables.head.xMin), xMax: round(font.tables.head.xMax), yMin: round(font.tables.head.yMin), yMax: round(font.tables.head.yMax) },
    resolution: 1000,
    original_font_information: { format: 0, copyright: 'Montserrat, SIL Open Font License 1.1', fontFamily: 'Montserrat', fontSubfamily: 'ExtraBold' },
}

const out = path.join(root, 'sources/data/nameFont.js')
fs.writeFileSync(out, `// Generated by scripts/build-name-font.mjs from Montserrat ExtraBold (SIL OFL 1.1). Do not edit.\nexport default ${JSON.stringify(typeface)}\n`)
console.log(`Wrote ${Object.keys(glyphs).length} glyphs to ${path.relative(root, out)}`)
